import { create_list_edit_phase_tasks } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  props: {
    taskdeletion: Boolean,
    projData: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      loading: false
    };
  },
  watch: {
    taskdeletion: {
      async handler() {
        if (this.taskdeletion == true) {
          await this.get_all_org_users();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_name(value) {
      var data = "";
      this.orgUsers.forEach(element => {
        if (element.user_email_id == value) {
          data = element.full_user_name;
        }
      });
      return data;
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_phase_tasks, {
          input: {
            task_id: this.projData.task_id,
            phase_id: this.projData.phase_id,
            action_type: 'DELETE'
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_phase_tasks);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
